"""호드리구 설명(NOTE) 문구. build_rodrygo.py가 수치를 넘겨 줌."""

def make_note(c):
    ST, M, E = c["ST"], c["M"], c["E"]
    s, r = ST["sntro"], ST["rmro"]
    def d(x):
        y, m, dd = x.split("-"); return f"{int(y)}.{int(m)}.{int(dd)}"
    L = []
    L.append(f"호드리구(산투스·레알 마드리드)의 클럽 공식 경기 {c['NG']}경기({d(M[0][0])} 아틀레치쿠 미네이루전 ~ {d(M[-1][0])} 헤타페전)에서 나온 "
             f"{c['NGo']}골 {c['NA']}도움(PK 골 {c['NPK']}개), 친선경기·대표팀(브라질·U23·U20·U17)·레알 마드리드 카스티야(2군) 경기 제외")
    L.append(f"클럽별 경기·골·도움: 산투스 {s[0]}·{s[1]}·{s[2]}, 레알 마드리드 {r[0]}·{r[1]}·{r[2]}. 출전 분 합계 {c['MIN_TOT']:,}분")
    L.append("출처: 경기 목록·출전 분(연장·퇴장 반영)은 Transfermarkt 선수 경기 성적, 골 시간·골 뒤 스코어·PK·도움은 Transfermarkt 경기 리포트(골·도움이 있는 경기와 리그 밖 대회 경기 전부)를 쓰고 FotMob 경기 이벤트·선수 경기 기록과 대조함")
    L.append("경기 수·골은 영어 위키백과 클럽·시즌별 기록(산투스 80경기 17골, 레알 297경기 71골)과 FotMob 클럽별 통산과 같음. 위키백과는 2025 클럽 월드컵 3경기를 2024-25에 넣음(Transfermarkt는 2025 시즌)")
    L.append("뺀 기록: 레알 마드리드 카스티야(2군, 3부 세군다 B) 2019-20 3경기 2골 0도움은 2군이라 제외. 1군 소속 팀은 모든 시즌 1부 프로 리그(브라질 세리에 A·라리가)")
    L.append("출전 분: 아래 중단 경기 1개 말고는 Transfermarkt 출전 분 그대로(90분 추정 없음). 2020.1.12 수페르코파 결승 아틀레티코전(0:0 연장 뒤 승부차기)은 60분에 들어가 연장까지 뛰어 60분(FotMob 30분). "
             "FotMob 선수 경기 기록은 2018.4.14 세아라전(골)·2019.5.15 아틀레치쿠 미네이루전을 출전 안 함으로 적었지만 Transfermarkt·위키백과 출전 수 기준으로 넣음")
    L.append("골: FotMob 경기 이벤트가 있는 경기는 수·PK 여부·분이 모두 같음. FotMob에 경기 자료가 없는 캄페오나투 파울리스타 2018~2019(22경기)와 이벤트가 빈 코파 두 브라질 2경기의 골 6개(2018.1.25 폰치 프레타전·1.28 이투아누전·3.27 파우메이라스전, 2019.2.18 과라니전·3.7 아메리카 RN전·4.11 아틀레치쿠 고이아니엔시전)는 Transfermarkt 단일 출처(위키백과 시즌 골 수와는 같음). "
             "PK 골 3개(2022.10.16 바르셀로나전, 10.25 라이프치히전, 11.2 셀틱전). 자책골로 뺄 골 없음")
    L.append(f"도움: Transfermarkt와 FotMob이 함께 센 것만 넣음. 도움 {c['NA']} = Transfermarkt 리포트 {c['N_TM_A']} − PK 유도 5(2023.2.15 엘체전 벤제마, 2024.4.30 바이에른전 비니시우스, 2025.1.19 라스팔마스전·2025.9.16 마르세유전·2025.12.20 세비야전 음바페) "
             "− 상대 자책골 1(2020.11.25 인테르전 59분 하키미 자책골, Transfermarkt 'Shot on goal') − 확인 안 된 단일 출처 2")
    L.append("FotMob 경기 이벤트에는 도움자가 비어 있지만 FotMob 선수 경기 기록이 호드리구 도움으로 센 5개는 넣음: 2018.6.3 비토리아전 73분 가브리에우 바르보자 골, 2018.6.6 코린치안스전 75분 비토르 페하스 골, 2018.7.25 플라멩구전 34분 가브리에우 바르보자 골, 2019.12.11 브뤼허전 64분 비니시우스 골, 2022.1.5 알코야노전 39분 밀리탕 골(코너킥)")
    L.append("넣지 않은 도움(Transfermarkt에만 있고 다른 출처 2곳이 확인하지 않음): 2019.3.2 파울리스타 오에스치전 90+6분 비토르 페하스 골(FotMob 자료 없음, Lance!·Jovem Pan 기사에 호드리구 도움 언급 없음), 2019.4.17 코파 두 브라질 바스쿠전 66분 장 모타 골(Jovem Pan 기사만 호드리구 패스로 적고 JB 기사는 언급 없음)")
    L.append(f"도움 합계 비교: Transfermarkt 65(PK 유도·자책골 포함)·FotMob 경력 합계 59(산투스 8·레알 51)·이 계산기 {c['NA']}(산투스 {s[2]}·레알 {r[2]})")
    L.append("날짜는 현지 날짜: 브라질 경기는 경기 시각(UTC)을 상파울루 시간으로, 남미 원정은 개최국 시간으로 바꾼 날짜(Transfermarkt 리포트 날짜는 중부 유럽 시간이라 저녁 경기는 하루 늦음). 유럽 경기는 개최지 날짜, 2025 클럽 월드컵은 미국 동부 시간, 수페르코파(사우디)·2023년 2월 클럽 월드컵(모로코)·2024 인터콘티넨털컵(카타르)은 개최지 시간")
    src = c["SRC"]
    L.append(f"상대 Elo는 같은 경기를 다룬 다른 선수 자료(비니시우스·벤제마·벨링엄·음바페 등) 값, 같은 팀·같은 시즌 다른 선수 자료 값, 그 시즌 순위를 리그 순위값에 넣은 값, 직접 추정 순으로 씀(기록 {len(E)}개: 같은 경기 {src['같은 경기 다른 선수 자료']}, 같은 팀·시즌 {src['팀×시즌 통합표']}, 순위표 {src['순위표+리그 모형']}, 직접 {src['직접 추정']})")
    L.append("브라질 세리에 A·B는 달력 연도 시즌의 최종 순위(위키백과·CBF 순위표로 확인)에 다른 선수 자료(네이마르 등)의 순위별 값을 씀. 2018 세리에 A 스포르트 헤시피는 승점 3 삭감으로 18위(Transfermarkt 표는 17위). 세리에 B 2019 4위(아틀레치쿠 고이아니엔시)는 다른 선수 자료 3위 1429·5위 1403의 가운데 1416")
    L.append("캄페오나투 파울리스타 상대는 그 해 전국 리그 수준으로 정함(세리에 A·B 순위값, 세리에 A~D 밖 이투아누 2018은 4부 이하 1200, 추정). 코파 두 브라질 아메리카 RN 2019(세리에 D)는 4부 이하 1200(추정)")
    L.append("직접 추정(모두 '추정'): 나시오나우(우루과이) 2018 1635(연간 순위 2위, 다른 선수 자료 우루과이 연간 2위 값과 같음), 카세레뇨 2022-23·아란디나 2023-24 1150(스페인 4부 세군다 페데라시온, 다른 선수 자료 4부 값과 같음). 갈라타사라이·브뤼허·샤흐타르·셰리프·셀틱·알아흘리·파추카·카이라트는 다른 선수 자료의 추정값을 그대로 씀")
    L.append("대회 비중: 캄페오나투 파울리스타(상파울루 주 선수권)는 조별·토너먼트 모두 국내컵 하위 라운드 비중(네이마르 자료와 같음), 조별은 리그식, 8강·준결승 두 경기는 합산. 코파 두 브라질·코파 델 레이는 국내컵(16강까지 낮은 비중, 8강 이후 높은 비중), 수페르코파(4팀) 준결승은 국내컵 준결승, 결승과 UEFA 슈퍼컵은 국내컵 결승 비중. "
             "리베르타도레스 2018 조별·16강은 리베르타도레스 조별 비중. 챔스 리그 단계(2024-25부터)는 조별 비중, 녹아웃 플레이오프는 16강 비중. 클럽 월드컵·인터콘티넨털컵은 클럽 월드컵 비중, 2025 클럽 월드컵 조별은 리그식(무승부 1점)")
    L.append(f"두 경기 합산 기록 {c['NTIE']}개는 합산 S로 계산함: 챔스(원정 다득점 2020-21까지, 연장 있음), 코파 델 레이 준결승(원정 다득점 없음, 연장 있음), 코파 두 브라질·파울리스타(원정 다득점·연장 없이 승부차기), 리베르타도레스 2018(원정 다득점 있고 연장 없음). 호드리구가 뛰지 않은 다른 차전 스코어는 Transfermarkt 경기 리포트로 채움")
    L.append("2018.8.21 리베르타도레스 16강 1차전 인데펜디엔테 원정은 그라운드에서 0:0이었으나 산투스의 출전 자격 없는 선수 기용으로 0:3 몰수패 처리됨(Transfermarkt 3:0, 골 기록 없음). 출전 57분은 그대로 셈. 2018.8.28 2차전(0:0)은 관중 소요로 81분(후반 36분)에 중단·종료돼 Transfermarkt 90분 대신 실제 뛴 81분으로 셈(El Universo·AP, Goal.com 기사)")
    L.append("연장 기록: 2022.1.12 수페르코파 준결승 바르셀로나전 98분 발베르데 골 도움")
    L.append("시즌 구분: 산투스는 달력 연도(2017·2018·2019), 레알 마드리드는 8월 1일 기준(2020년 8월 챔스 맨시티전은 2019-20). 클럽 구분은 2019.7.1 전 산투스, 이후 레알 마드리드")
    L.append("수상 기록은 Transfermarkt 업적 페이지 기준: 챔피언스리그 2021-22·2023-24, 라리가 2019-20·2021-22·2023-24, 코파 델 레이 2022-23, 수페르코파 2019-20·2021-22·2023-24, UEFA 슈퍼컵 2022·2024, 클럽 월드컵 2022(2023년 2월)·인터콘티넨털컵 2024. 산투스 우승 없음, 개인 수상은 업적 페이지에 없음. 대표팀 기록은 뺌")
    L.append("2026.11.17 기준 현역(레알 마드리드). 마지막 반영 경기 2026.3.2 헤타페전(라리가). 그 뒤 무릎 십자인대 부상으로 2026.11.7 경기까지 결장(2026.11.17 수집)")
    return "\n".join(L)
